svg.script:

(function() {
  const root = document.getElementById('p10-svg-root');

  // Mudar aba ativa
  function setTab(tabName) {
    if (tabName === 'vpp23') {
      root.classList.remove('show-vpc');
      document.getElementById('p10-tab-vpp23').classList.add('active');
      document.getElementById('p10-tab-vpc').classList.remove('active');
      showInfoBlock('p10-info-default-vpp23');
    } else {
      root.classList.add('show-vpc');
      document.getElementById('p10-tab-vpc').classList.add('active');
      document.getElementById('p10-tab-vpp23').classList.remove('active');
      showInfoBlock('p10-info-default-vpc');
    }
    // Limpar hotspots ativos
    document.querySelectorAll('#p10-svg-root .hotspot').forEach(hs => hs.classList.remove('active-hs'));
  }

  // Mostrar bloco de informações no painel
  function showInfoBlock(id) {
    document.querySelectorAll('#p10-svg-root .panel-info-block').forEach(b => {
      b.style.display = 'none';
    });
    const target = document.getElementById(id);
    if (target) {
      target.style.display = 'block';
    }
  }

  // Adicionar ouvintes para abas
  document.getElementById('p10-tab-vpp23').addEventListener('click', () => setTab('vpp23'));
  document.getElementById('p10-tab-vpc').addEventListener('click', () => setTab('vpc'));

  // Acessibilidade via teclado nas abas
  document.getElementById('p10-tab-vpp23').addEventListener('keydown', (e) => {
    if (e.key === 'Enter' || e.key === ' ') { e.preventDefault(); setTab('vpp23'); }
  });
  document.getElementById('p10-tab-vpc').addEventListener('keydown', (e) => {
    if (e.key === 'Enter' || e.key === ' ') { e.preventDefault(); setTab('vpc'); }
  });

  // Configuração dos Hotspots
  const hotspots = [
    { hsId: 'p10-hs-1', infoId: 'p10-info-hs1' },
    { hsId: 'p10-hs-2', infoId: 'p10-info-hs2' },
    { hsId: 'p10-hs-3', infoId: 'p10-info-hs3' },
    { hsId: 'p10-hs-4', infoId: 'p10-info-hs4' },
    { hsId: 'p10-hs-5', infoId: 'p10-info-hs5' },
    { hsId: 'p10-hs-6', infoId: 'p10-info-hs6' }
  ];

  hotspots.forEach(item => {
    const el = document.getElementById(item.hsId);
    if (el) {
      const activateHotspot = () => {
        document.querySelectorAll('#p10-svg-root .hotspot').forEach(hs => hs.classList.remove('active-hs'));
        el.classList.add('active-hs');
        showInfoBlock(item.infoId);
      };
      el.addEventListener('click', activateHotspot);
      el.addEventListener('keydown', (e) => {
        if (e.key === 'Enter' || e.key === ' ') { e.preventDefault(); activateHotspot(); }
      });
    }
  });

  // Iniciar na via VPP23 por padrão
  setTab('vpp23');
})();
